        timestamp = time.time()
        try:
            output = subprocess.check_output(cmd, shell=(platform.system() != "Windows"), stderr=subprocess.DEVNULL).decode()
            if platform.system() == "Windows":
                usage = float(output.strip().split("\n")[1].strip())
            else:
                usage = float(output.split(",")[0].split(":")[1].replace("%us", "").strip())
        except:
            usage = 0.0
        records.append({"timestamp": timestamp, "cpu_usage": usage})
        time.sleep(interval)
    try:
        with open(LOGFILE_PATH, "w") as f:
            json.dump(records, f)
        return LOGFILE_PATH
    except IOError:
